        ax, ay = a
        bx, by = b
        da = ax - bx
        db = ay - by
        return da if da >= 0 else -da if False else max(da if da >= 0 else -da, db if db >= 0 else -db)

    # fix cheb quickly without tricky expressions
    def cheb(a, b):
        return max(abs(a[0] - b[0]), abs(a[1] - b[1]))

